def install_workspace(base):
    original=base.workspace
    def workspace():
        w=original()
        if not any(p.get('id')==PAGE_ID for p in w.get('pages',[])): w['pages'].append(page());w=base.save(w)
        return w
    base.workspace=workspace

def install_editor(doc): return doc.replace("'living-water-candidate-03'])","'living-water-candidate-03','living-water-candidate-04'])")

def tile_markup(item):
    stream,kind,title,dore,weight,crop,href=item
    return '<a class="tile" href="%s" data-dore="%s" data-weight="%s" data-crop="%s"><div class="tcopy"><span class="index">%s</span><h3>%s</h3></div></a>'%(html.escape(href,quote=True),dore,weight,html.escape(crop,quote=True),html.escape(kind),html.escape(title))

def nav_markup():
    groups=[]
    for key in 'abcd':
        speed,origin=STREAM_META[key]
        body=''.join(tile_markup(x) for x in ITEMS if x[0]==key)
        groups.append('<div class="stream-wrap %s" data-speed="%s" data-origin="%s"><div class="stream %s">%s</div></div>'%(key,speed,origin,key,body))
    return '<section class="live-nav" id="liveNav"><div class="live-nav-stage"><div class="dore-river-bg" aria-hidden="true"><img id="riverPlateA" class="river-plate" alt=""><img id="riverPlateB" class="river-plate" alt=""></div><div class="dawn-horizon"></div><div class="live-water"><div class="current-line l1"></div><div class="current-line l2"></div><div class="current-line l3"></div><div class="current-line l4"></div>%s</div><div class="light-engine c" id="lightC" aria-hidden="true"><canvas id="godraysCanvas"></canvas></div><div class="light-engine d off" id="lightD" aria-hidden="true"></div><div class="light-switch"><button type="button" class="on" data-light="c">C · God Rays</button><button type="button" data-light="d">D · LightRays</button><button type="button" data-light="off">Off</button></div></div></section>'%''.join(groups)

